const item = $input.first().json;
const t = String(item.cleanText || item.safeText || '').toLowerCase();

// 0 = bug report, 1 = human handoff / escalation, 2 = general KB question
let intentRoute = 2;

const bugPattern = /\b(bug|error|crash(ed|ing)?|broken|not working|doesn'?t work|issue|fail(ed|ing)?|exception|500|502|503|stack trace|glitch)\b/;
const handoffPattern = /\b(human|agent|representative|real person|talk to (a )?person|speak to (a )?(human|agent|person)|escalate|manager|refund|cancel my|cancel account|complaint|angry|unacceptable)\b/;

if (bugPattern.test(t)) {
  intentRoute = 0;
} else if (handoffPattern.test(t)) {
  intentRoute = 1;
}

return [{ json: { ...item, intentRoute } }];
